// src/__tests__/youtube-auth.test.ts
import { describe, it, expect } from "vitest";
import { buildOAuthClient, type YoutubeAuthEnv } from "../sources/youtube/auth.js";

const valid: YoutubeAuthEnv = { clientId: "id", clientSecret: "secret", refreshToken: "refresh" };

describe("buildOAuthClient", () => {
  it("returns a client with the refresh token set when all fields present", () => {
    const c = buildOAuthClient(valid);
    expect(typeof c.generateAuthUrl).toBe("function");
    expect(c.credentials.refresh_token).toBe("refresh");
  });
  it("throws naming the missing var", () => {
    expect(() => buildOAuthClient({ ...valid, clientId: undefined })).toThrow(/YOUTUBE_CLIENT_ID/);
    expect(() => buildOAuthClient({ ...valid, clientSecret: undefined })).toThrow(/YOUTUBE_CLIENT_SECRET/);
    expect(() => buildOAuthClient({ ...valid, refreshToken: undefined })).toThrow(/YOUTUBE_REFRESH_TOKEN/);
  });
});

/**
 * Head-to-head test: current vs proposed research config.
 *
 * Tests the same research prompt against:
 *   A) CURRENT:   gemini-3.1-flash-image-preview + disableTools: true
 *   B) PROPOSED:  gemini-3.1-flash-image-preview + output:{format:"text"} + websearchGrounding
 *   C) FALLBACK:  gemini-2.5-flash + websearchGrounding (text-only model, sanity check)
 *
 * Use a niche tool name that's unlikely to be in training data, so we can tell
 * whether websearchGrounding is actually being used.
 */
import "dotenv/config";
import { NeuroLink } from "@juspay/neurolink";

const TEST_PROMPT = `Research the following developer tool and report findings in 100 words:

Tool: "n8n self-host with Docker Compose"
- What is it? (one sentence)
- Latest stable version (be specific, give version number)
- Where is it documented? (give URL)
- One real install command

Be precise. Cite at least one URL. If you don't know, say so.`;

interface RunResult {
  label: string;
  ok: boolean;
  ms: number;
  contentLen: number;
  contentPreview: string;
  toolsUsed: string[];
  error?: string;
  raw?: any;
}

async function run(label: string, fn: () => Promise<any>): Promise<RunResult> {
  const t0 = Date.now();
  try {
    const r = await fn();
    const ms = Date.now() - t0;
    const content = String(r?.content ?? "");
    return {
      label,
      ok: true,
      ms,
      contentLen: content.length,
      contentPreview: content.slice(0, 600),
      toolsUsed: (r?.toolsUsed ?? []).map((t: any) => t?.toolName ?? t?.name ?? String(t)),
      raw: r,
    };
  } catch (e: any) {
    return {
      label,
      ok: false,
      ms: Date.now() - t0,
      contentLen: 0,
      contentPreview: "",
      toolsUsed: [],
      error: String(e?.message ?? e),
    };
  }
}

async function main() {
  const neurolink = new NeuroLink();

  console.log("=== Head-to-head research-config test ===");
  console.log(`Prompt: ${TEST_PROMPT.slice(0, 100)}...\n`);

  // A) CURRENT — what researcher.ts uses today
  const A = await run("A. CURRENT (image-preview + disableTools)", async () =>
    neurolink.generate({
      input: { text: TEST_PROMPT },
      provider: "vertex",
      model: "gemini-3.1-flash-image-preview",
      disableTools: true,
      maxTokens: 8192,
      timeout: "120s",
    } as any)
  );

  // B) PROPOSED — same model, but route to text path with web search
  const B = await run("B. PROPOSED (image-preview + output.format=text + websearchGrounding)", async () =>
    neurolink.generate({
      input: { text: TEST_PROMPT },
      provider: "vertex",
      model: "gemini-3.1-flash-image-preview",
      output: { format: "text" },
      enabledToolNames: ["websearchGrounding"],
      maxTokens: 8192,
      timeout: "180s",
    } as any)
  );

  // C) FALLBACK — text-only model with web search (sanity baseline)
  const C = await run("C. FALLBACK (gemini-2.5-flash + websearchGrounding)", async () =>
    neurolink.generate({
      input: { text: TEST_PROMPT },
      provider: "vertex",
      model: "gemini-2.5-flash",
      enabledToolNames: ["websearchGrounding"],
      maxTokens: 8192,
      timeout: "180s",
    } as any)
  );

  for (const r of [A, B, C]) {
    console.log("\n" + "=".repeat(80));
    console.log(`${r.label}`);
    console.log("=".repeat(80));
    console.log(`ok=${r.ok}  ms=${r.ms}  contentLen=${r.contentLen}  toolsUsed=${JSON.stringify(r.toolsUsed)}`);
    if (r.error) console.log(`ERROR: ${r.error}`);
    if (r.contentPreview) console.log(`PREVIEW (first 600 chars):\n${r.contentPreview}`);
  }

  console.log("\n" + "=".repeat(80));
  console.log("VERDICT");
  console.log("=".repeat(80));
  console.log(`A current  → ${A.ok ? `${A.contentLen} chars, tools=${A.toolsUsed.length}` : "FAIL: " + A.error}`);
  console.log(`B proposed → ${B.ok ? `${B.contentLen} chars, tools=${B.toolsUsed.length}` : "FAIL: " + B.error}`);
  console.log(`C fallback → ${C.ok ? `${C.contentLen} chars, tools=${C.toolsUsed.length}` : "FAIL: " + C.error}`);
}

main().catch((e) => { console.error(e); process.exit(1); });

/**
 * Round 2: deeper inspection of websearchGrounding tool calls.
 * Dumps full tool inputs/outputs so we can see what the search returned.
 * Also tests the multi-item batched-research prompt shape that researcher.ts uses.
 */
import "dotenv/config";
import { NeuroLink } from "@juspay/neurolink";

const MULTI_ITEM_PROMPT = `You are a senior developer researching tools so another engineer can install and use them.

For each numbered tool below, return:
1. ## <NAME> — <one-sentence description>
2. **URL**: <official docs/repo URL>
3. **Latest version**: <version number, or "unknown">
4. **Install**: <real install command>
5. **Status**: active / deprecated / unknown
6. **Notes**: any setup requirement (auth, license, free tier)

Tools to research:
1. n8n (workflow automation, self-host with Docker Compose)
2. Whisper.cpp (OpenAI Whisper speech-to-text in C++)
3. Helix DB (graph + vector DB written in Rust)

Be precise. If you don't know, say "unknown" — do not guess.`;

interface RunResult {
  label: string;
  ok: boolean;
  ms: number;
  contentLen: number;
  contentPreview: string;
  toolCallDetails: any[];
  raw?: any;
  error?: string;
}

async function run(label: string, fn: () => Promise<any>): Promise<RunResult> {
  const t0 = Date.now();
  try {
    const r = await fn();
    const ms = Date.now() - t0;
    const content = String(r?.content ?? "");
    const toolCallDetails: any[] = [];
    for (const t of (r?.toolsUsed ?? [])) {
      toolCallDetails.push({
        name: t?.toolName ?? t?.name ?? null,
        input: t?.args ?? t?.input ?? t?.parameters ?? null,
        output: t?.result ?? t?.output ?? t?.response ?? null,
      });
    }
    return { label, ok: true, ms, contentLen: content.length,
      contentPreview: content.slice(0, 1500), toolCallDetails, raw: r };
  } catch (e: any) {
    return { label, ok: false, ms: Date.now() - t0, contentLen: 0,
      contentPreview: "", toolCallDetails: [], error: String(e?.message ?? e) };
  }
}

async function main() {
  const neurolink = new NeuroLink();
  console.log("=== Round 2: deep inspection of tool calls ===\n");

  const A = await run("A. PROPOSED — image-preview + format:text + websearchGrounding (multi-item)", async () =>
    neurolink.generate({
      input: { text: MULTI_ITEM_PROMPT },
      provider: "vertex",
      model: "gemini-3.1-flash-image-preview",
      output: { format: "text" },
      enabledToolNames: ["websearchGrounding"],
      maxTokens: 8192,
      timeout: "300s",
    } as any)
  );

  for (const r of [A]) {
    console.log("\n" + "=".repeat(80));
    console.log(r.label);
    console.log("=".repeat(80));
    console.log(`ok=${r.ok}  ms=${r.ms}  contentLen=${r.contentLen}  numToolCalls=${r.toolCallDetails.length}`);
    if (r.error) { console.log("ERROR: " + r.error); continue; }

    console.log("\n--- TOOL CALLS ---");
    for (let i = 0; i < r.toolCallDetails.length; i++) {
      const t = r.toolCallDetails[i];
      console.log(`\n[Tool ${i+1}] ${t.name}`);
      console.log("  INPUT: " + JSON.stringify(t.input).slice(0, 300));
      console.log("  OUTPUT: " + JSON.stringify(t.output).slice(0, 800));
    }

    console.log("\n--- CONTENT ---");
    console.log(r.contentPreview);
  }

  // also dump raw shape so we know what fields exist
  console.log("\n--- RAW response keys ---");
  console.log(Object.keys(A.raw ?? {}));
  console.log("\ntoolsUsed:", JSON.stringify(A.raw?.toolsUsed));
  console.log("\ntoolExecutions:");
  for (const exec of (A.raw?.toolExecutions ?? [])) {
    console.log("  - tool:", exec?.toolName ?? exec?.name);
    console.log("    args:", JSON.stringify(exec?.args ?? exec?.input).slice(0, 300));
    console.log("    result:", JSON.stringify(exec?.result ?? exec?.output).slice(0, 1200));
  }
  console.log("\nfinishReason:", A.raw?.finishReason);
}

main().catch((e) => { console.error(e); process.exit(1); });

import { describe, expect, it } from "vitest";
import { COMPOSED_DOC_MAX_CHARS, composeDoc, sha256Hex, type ComposedDocInput } from "../search/doc.js";

const base: ComposedDocInput = {
  title: "T",
  category: "Tech & Coding",
  tags: ["a", "b"],
  topics: ["topic1"],
  takeaways: ["do X", "do Y"],
  tools: [
    { name: "toolA", description: "descA" },
    { name: "toolB", description: "" },
  ],
  description: "desc",
  transcript: "spoken words",
};

describe("composeDoc", () => {
  it("orders fields with transcript last", () => {
    const doc = composeDoc(base);
    expect(doc.indexOf("T")).toBeLessThan(doc.indexOf("do X"));
    expect(doc.endsWith("spoken words")).toBe(true);
    expect(doc).toContain("toolA: descA");
    expect(doc).toContain("toolB");
  });

  it("skips empty parts without blank lines", () => {
    const doc = composeDoc({ ...base, tags: [], description: "" });
    expect(doc).not.toMatch(/\n\n/);
  });

  it("truncates to the budget, sacrificing transcript first", () => {
    const doc = composeDoc({ ...base, transcript: "x".repeat(10_000) });
    expect(doc.length).toBe(COMPOSED_DOC_MAX_CHARS);
    expect(doc).toContain("do X");
  });
});

describe("sha256Hex", () => {
  it("is stable and input-sensitive", () => {
    expect(sha256Hex("abc")).toBe(sha256Hex("abc"));
    expect(sha256Hex("abc")).not.toBe(sha256Hex("abd"));
    expect(sha256Hex("abc")).toMatch(/^[0-9a-f]{64}$/);
  });
});

import fs from "node:fs/promises";
import os from "node:os";
import path from "node:path";
import type { DatabaseSync } from "node:sqlite";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { openSearchDb } from "../search/db.js";
import { buildSearchRecords, indexRecords, type SearchStates } from "../search/indexer.js";
import { clampLimit, getVideo, hybridSearch, searchTools, stats, toFtsQuery } from "../search/query.js";

function kb(transcript: string, takeaway: string, topics: string[]) {
  return {
    category: "Tech & Coding",
    transcript,
    visual_description: "",
    key_takeaways: [{ timestamp: "0:01", takeaway }],
    topics,
  };
}

const states: SearchStates = {
  knowledge: {
    "a_1.mp4": kb("bot detection cloudflare bypass scraping stealth", "use cloakbrowser", ["scraping"]),
    "b_2.mp4": kb("terminal remote access from browser", "use vibetunnel", ["terminals"]),
    "c_3.mp4": kb("kitchen renovation ideas", "paint the wall", ["interior"]),
  },
  classifications: {
    "a_1.mp4": {
      category: "Tech & Coding",
      tags: ["scraping"],
      description: "CloakBrowser video",
      code: "AAA",
      username: "a",
    },
    "b_2.mp4": {
      category: "Tech & Coding",
      tags: ["cli"],
      description: "VibeTunnel video",
      code: "BBB",
      username: "b",
    },
    "c_3.mp4": {
      category: "Interior Design & Home",
      tags: ["home"],
      description: "Kitchen video",
      code: "CCC",
      username: "c",
    },
  },
  catalog: [
    { filename: "a_1.mp4", description: "CloakBrowser stealth chromium", taken_at: "2026-07-01" },
    { filename: "b_2.mp4", description: "VibeTunnel remote terminal", taken_at: "2026-07-02" },
    { filename: "c_3.mp4", description: "Kitchen makeover", taken_at: "2026-07-03" },
  ],
  analysis: {
    "a_1.mp4": {
      actionable_items: [
        {
          name: "CloakBrowser",
          type: "tool_install",
          description: "stealth chromium",
          url: "https://example.com/cloak",
        },
      ],
    },
  },
  research: { "a_1.mp4": { items: [{ item_name: "CloakBrowser", url_status: "live" }] } },
  verifications: { "a_1.mp4": { overall_score: "verified_useful" } },
  linksV2: {},
};

// Fake 3-dim embedding space: video A near [1,0,0], B near [0,1,0], C near [0,0,1]
const VEC_BY_DOC_SNIPPET: [string, number[]][] = [
  ["cloakbrowser", [1, 0, 0.05]],
  ["vibetunnel", [0, 1, 0.05]],
  ["kitchen", [0, 0.05, 1]],
];

async function embedder(texts: string[]): Promise<number[][]> {
  return texts.map((t) => {
    const lower = t.toLowerCase();
    const match = VEC_BY_DOC_SNIPPET.find(([snippet]) => lower.includes(snippet));
    return match ? match[1] : [0.3, 0.3, 0.3];
  });
}

let tmpDir: string;
let db: DatabaseSync;

beforeEach(async () => {
  tmpDir = await fs.mkdtemp(path.join(os.tmpdir(), "dopamine-query-"));
  db = openSearchDb(path.join(tmpDir, "search.db"));
  await indexRecords(db, buildSearchRecords(states), embedder, "test-model");
});

afterEach(async () => {
  db.close();
  await fs.rm(tmpDir, { recursive: true, force: true });
});

describe("toFtsQuery", () => {
  it("quotes every term, keeping operator words searchable as literals", () => {
    expect(toFtsQuery('cloudflare "bypass"')).toBe('"cloudflare" OR "bypass"');
    expect(toFtsQuery("black and white")).toBe('"black" OR "and" OR "white"');
    expect(toFtsQuery("  ")).toBe('""');
  });
});

describe("clampLimit", () => {
  it("clamps NaN, negatives, floats, and huge values", () => {
    expect(clampLimit(undefined, 10)).toBe(10);
    expect(clampLimit(Number.NaN, 10)).toBe(10);
    expect(clampLimit(-5, 10)).toBe(1);
    expect(clampLimit(3.9, 10)).toBe(3);
    expect(clampLimit(10_000, 10)).toBe(100);
  });
});

describe("hybridSearch", () => {
  it("finds by keyword in fts_only mode", () => {
    const result = hybridSearch(db, "cloudflare", null);
    expect(result.mode).toBe("fts_only");
    expect(result.hits[0].id).toBe("a_1");
    expect(result.hits[0].topTools).toContain("CloakBrowser");
  });

  it("uses the query vector in hybrid mode", () => {
    const result = hybridSearch(db, "zzz-no-keyword-match", [0, 0.9, 0.1]);
    expect(result.mode).toBe("hybrid");
    expect(result.hits[0].id).toBe("b_2");
  });

  it("only compares same-model embeddings when queryModel is given, and reports the honest mode", () => {
    // Query vector points at video B, but the index was built with "test-model" —
    // a mismatched queryModel must ignore all vectors and fall back to FTS signal only.
    const mismatch = hybridSearch(db, "zzz-no-keyword-match", [0, 0.9, 0.1], { queryModel: "other-model" });
    expect(mismatch.hits).toHaveLength(0);
    expect(mismatch.mode).toBe("fts_only");
    const match = hybridSearch(db, "zzz-no-keyword-match", [0, 0.9, 0.1], { queryModel: "test-model" });
    expect(match.hits[0].id).toBe("b_2");
    expect(match.mode).toBe("hybrid");
  });

  it("applies category filter and limit", () => {
    // OR semantics: each term matches a different video, so all three are candidates
    const query = "cloudflare terminal kitchen";
    const filtered = hybridSearch(db, query, null, { category: "Interior Design & Home" });
    expect(filtered.hits.map((h) => h.id)).toEqual(["c_3"]);
    const limited = hybridSearch(db, query, null, { limit: 1 });
    expect(limited.hits).toHaveLength(1);
  });
});

describe("getVideo", () => {
  it("returns full detail including transcript and tools", () => {
    const detail = getVideo(db, "a_1");
    expect(detail).not.toBeNull();
    expect(detail?.transcript).toContain("cloudflare");
    expect(detail?.tools[0].name).toBe("CloakBrowser");
    expect(detail?.verification).toBe("verified_useful");
  });

  it("returns null for unknown ids", () => {
    expect(getVideo(db, "nope")).toBeNull();
  });
});

describe("searchTools", () => {
  it("matches name substrings case-insensitively", () => {
    const hits = searchTools(db, "cloak");
    expect(hits).toHaveLength(1);
    expect(hits[0]).toMatchObject({ name: "CloakBrowser", urlStatus: "live", videoId: "a_1" });
  });

  it("filters by type", () => {
    expect(searchTools(db, "cloak", "workflow")).toHaveLength(0);
    expect(searchTools(db, "cloak", "tool_install")).toHaveLength(1);
  });
});

describe("stats", () => {
  it("reports totals, categories, and embedding coverage", () => {
    const s = stats(db);
    expect(s.totalVideos).toBe(3);
    expect(s.embeddedVideos).toBe(3);
    expect(s.model).toBe("test-model");
    expect(s.categories.find((c) => c.name === "Tech & Coding")?.count).toBe(2);
    expect(s.builtAt).not.toBe("");
  });
});

import { describe, expect, it } from "vitest";
import { isHost } from "../agents/researcher.js";

describe("isHost", () => {
  it("matches the host itself and its subdomains", () => {
    expect(isHost("https://npmjs.com/package/zod", "npmjs.com")).toBe(true);
    expect(isHost("https://www.npmjs.com/package/zod", "npmjs.com")).toBe(true);
    expect(isHost("https://registry.npmjs.org/zod", "npmjs.org")).toBe(true);
    expect(isHost("https://github.com/colinhacks/zod", "github.com")).toBe(true);
  });

  it("is not fooled by the host name appearing elsewhere in the URL", () => {
    // The substring check this replaced said yes to every one of these.
    expect(isHost("https://evil.example/npmjs.com", "npmjs.com")).toBe(false);
    expect(isHost("https://evil.example/?q=pypi.org", "pypi.org")).toBe(false);
    expect(isHost("https://github.com.evil.example/x", "github.com")).toBe(false);
    expect(isHost("https://notgithub.com/x/y", "github.com")).toBe(false);
  });

  it("treats missing or unparseable input as no match rather than throwing", () => {
    expect(isHost(null, "github.com")).toBe(false);
    expect(isHost(undefined, "github.com")).toBe(false);
    expect(isHost("", "github.com")).toBe(false);
    expect(isHost("not a url", "github.com")).toBe(false);
  });
});

import { describe, expect, it } from "vitest";
import { cosineSim, rrfMerge } from "../search/rank.js";

describe("cosineSim", () => {
  it("is 1 for identical, 0 for orthogonal, 0 for zero vectors", () => {
    expect(cosineSim([1, 2, 3], [1, 2, 3])).toBeCloseTo(1);
    expect(cosineSim([1, 0], [0, 1])).toBeCloseTo(0);
    expect(cosineSim([0, 0], [1, 1])).toBe(0);
  });

  it("works across Float32Array and number[] inputs", () => {
    expect(cosineSim(Float32Array.from([1, 0]), [1, 0])).toBeCloseTo(1);
  });
});

describe("rrfMerge", () => {
  it("ranks an id present in both lists above single-list ids", () => {
    const merged = rrfMerge([
      ["a", "b"],
      ["b", "c"],
    ]);
    expect(merged[0].id).toBe("b");
  });

  it("preserves order within a single list and handles empties", () => {
    const merged = rrfMerge([["x", "y", "z"], []]);
    expect(merged.map((m) => m.id)).toEqual(["x", "y", "z"]);
    expect(rrfMerge([[], []])).toEqual([]);
  });
});

import { mkdtemp, readFile, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import path from "node:path";
import { afterEach, describe, expect, it } from "vitest";
import { handleToolCall } from "../mcp/handlers.js";
import { type UsageEntry, createUsageLogger, formatEntry, tallyConfidence } from "../mcp/usage-log.js";

describe("tallyConfidence", () => {
  it("counts each level and always reports all three", () => {
    const t = tallyConfidence([{ confidence: "high" }, { confidence: "low" }, { confidence: "low" }]);
    expect(t).toEqual({ high: 1, medium: 0, low: 2 });
  });

  it("ignores an unrecognised level instead of inventing a key", () => {
    const t = tallyConfidence([{ confidence: "bogus" as never }, { confidence: "medium" }]);
    expect(Object.keys(t).sort()).toEqual(["high", "low", "medium"]);
    expect(t.medium).toBe(1);
  });
});

describe("formatEntry", () => {
  it("emits one newline-terminated JSON object with the timestamp first", () => {
    const line = formatEntry({ event: "call", tool: "search_corpus", ms: 12, ok: true }, "2026-01-01T00:00:00.000Z");
    expect(line.endsWith("\n")).toBe(true);
    expect(line.split("\n").filter(Boolean)).toHaveLength(1);
    expect(JSON.parse(line)).toEqual({
      at: "2026-01-01T00:00:00.000Z",
      event: "call",
      tool: "search_corpus",
      ms: 12,
      ok: true,
    });
  });
});

let dir: string | undefined;
afterEach(async () => {
  if (dir) await rm(dir, { recursive: true, force: true });
  dir = undefined;
});

describe("createUsageLogger", () => {
  it("appends one line per entry", async () => {
    dir = await mkdtemp(path.join(tmpdir(), "usage-"));
    const file = path.join(dir, "u.jsonl");
    const log = createUsageLogger(file, () => "T");
    log({ event: "call", tool: "a", ms: 1, ok: true });
    log({ event: "call", tool: "b", ms: 2, ok: false });
    // Writes are fire-and-forget, so poll for the expected line count rather
    // than racing a fixed sleep.
    let lines: string[] = [];
    for (let i = 0; i < 100 && lines.length < 2; i++) {
      await new Promise((r) => setTimeout(r, 10));
      lines = (await readFile(file, "utf8").catch(() => "")).trim().split("\n").filter(Boolean);
    }
    expect(lines).toHaveLength(2);
    expect(JSON.parse(lines[0]).tool).toBe("a");
    expect(JSON.parse(lines[1]).ok).toBe(false);
  });

  it("never throws when the path is unwritable — telemetry must not break a tool call", async () => {
    const log = createUsageLogger("/nonexistent-dir-xyz/u.jsonl", () => "T");
    expect(() => log({ event: "call", tool: "a", ms: 1, ok: true })).not.toThrow();
    await new Promise((r) => setTimeout(r, 20));
  });
});

describe("handleToolCall usage logging", () => {
  const baseDeps = {
    getDb: () => ({}) as never,
    getQueryVector: async () => null,
    embeddingModel: "m",
    missingDbHelp: "no db",
  };

  it("records the tool name and failure when the db is missing", async () => {
    const seen: UsageEntry[] = [];
    // getDb throwing is the pre-dispatch bail-out, which must still be visible:
    // "every call failed because the index was missing" is exactly the kind of
    // thing this log exists to surface.
    await handleToolCall(
      {
        ...baseDeps,
        getDb: () => {
          throw new Error("nope");
        },
        logUsage: (e) => seen.push(e),
      },
      "corpus_stats",
      {},
    );
    expect(seen).toHaveLength(1);
