describe("indexRecords", () => {
  let tmpDir: string;

  beforeEach(async () => {
    tmpDir = await fs.mkdtemp(path.join(os.tmpdir(), "dopamine-indexer-"));
  });

  afterEach(async () => {
    await fs.rm(tmpDir, { recursive: true, force: true });
  });

  it("embeds new records, skips unchanged on re-run, prunes deleted", async () => {
    const db = openSearchDb(path.join(tmpDir, "search.db"));
    const calls: string[][] = [];
    const embedder = async (texts: string[]): Promise<number[][]> => {
      calls.push(texts);
      return texts.map(() => [0.1, 0.2, 0.3]);
    };
    const records = buildSearchRecords(states);

    await indexRecords(db, records, embedder, "test-model");
    expect(calls).toHaveLength(1);

    await indexRecords(db, records, embedder, "test-model");
    expect(calls).toHaveLength(1);

    await indexRecords(db, [], embedder, "test-model");
    const count = db.prepare("SELECT COUNT(*) AS n FROM videos").get() as { n: number };
    expect(count.n).toBe(0);
    const ftsCount = db.prepare("SELECT COUNT(*) AS n FROM videos_fts").get() as { n: number };
    expect(ftsCount.n).toBe(0);
    db.close();
  });

  it("refreshes the FTS row when only the tail of a long transcript changes", async () => {
    // The embedded doc is truncated to 4000 chars, so a change past the cutoff
    // leaves docHash identical — the FTS gate must still catch it (contentHash
    // hashes the full FTS values, not the truncated doc).
    const db = openSearchDb(path.join(tmpDir, "search.db"));
    const embedder = async (texts: string[]): Promise<number[][]> => texts.map(() => [1, 0, 0]);
    const longTranscript = `${"x".repeat(6000)} ORIGINAL_TAIL`;
    const long: SearchStates = {
      ...states,
      knowledge: { "creator_1.mp4": { ...states.knowledge["creator_1.mp4"], transcript: longTranscript } },
    };
    await indexRecords(db, buildSearchRecords(long), embedder, "test-model");

    const changed: SearchStates = {
      ...long,
      knowledge: {
        "creator_1.mp4": {
          ...long.knowledge["creator_1.mp4"],
          transcript: longTranscript.replace("ORIGINAL_TAIL", "CHANGED_TAIL"),
        },
      },
    };
    await indexRecords(db, buildSearchRecords(changed), embedder, "test-model");
    const fts = db.prepare("SELECT transcript FROM videos_fts WHERE id = ?").get("creator_1") as {
      transcript: string;
    };
    expect(fts.transcript).toContain("CHANGED_TAIL");
    db.close();
  });

  it("refreshes the FTS row when only the caption changes", async () => {
    const db = openSearchDb(path.join(tmpDir, "search.db"));
    const embedder = async (texts: string[]): Promise<number[][]> => texts.map(() => [1, 0, 0]);
    await indexRecords(db, buildSearchRecords(states), embedder, "test-model");

    // caption is FTS-indexed but not part of the embedded doc
    const changed: SearchStates = {
      ...states,
      catalog: [{ ...states.catalog[0], caption: "brand new caption" }],
    };
    await indexRecords(db, buildSearchRecords(changed), embedder, "test-model");
    const fts = db.prepare("SELECT caption FROM videos_fts WHERE id = ?").get("creator_1") as { caption: string };
    expect(fts.caption).toBe("brand new caption");
    db.close();
  });

  it("re-embeds when the model changes", async () => {
    const db = openSearchDb(path.join(tmpDir, "search.db"));
    const calls: string[][] = [];
    const embedder = async (texts: string[]): Promise<number[][]> => {
      calls.push(texts);
      return texts.map(() => [1, 0, 0]);
    };
    const records = buildSearchRecords(states);
    await indexRecords(db, records, embedder, "model-a");
    await indexRecords(db, records, embedder, "model-b");
    expect(calls).toHaveLength(2);
    db.close();
  });
});

import { describe, it, expect, vi } from "vitest";
import { sleep, exponentialBackoff } from "../utils/rate-limit.js";

describe("sleep()", () => {
  it("resolves after the given delay", async () => {
    vi.useFakeTimers();
    const p = sleep(100);
    vi.advanceTimersByTime(100);
    await expect(p).resolves.toBeUndefined();
    vi.useRealTimers();
  });

  it("resolves immediately for 0ms", async () => {
    vi.useFakeTimers();
    const p = sleep(0);
    vi.advanceTimersByTime(0);
    await expect(p).resolves.toBeUndefined();
    vi.useRealTimers();
  });
});

describe("exponentialBackoff()", () => {
  it("returns success on first try when fn succeeds", async () => {
    const fn = vi.fn().mockResolvedValue(42);
    const result = await exponentialBackoff(fn, 3, 10);
    expect(result).toEqual({ success: true, value: 42 });
    expect(fn).toHaveBeenCalledTimes(1);
  });

  it("returns the value produced by fn", async () => {
    const fn = vi.fn().mockResolvedValue({ data: "hello" });
    const result = await exponentialBackoff(fn, 1, 10);
    expect(result).toEqual({ success: true, value: { data: "hello" } });
  });

  it("retries on failure and eventually succeeds", async () => {
    const fn = vi
      .fn()
      .mockRejectedValueOnce(new Error("transient"))
      .mockResolvedValue("ok");
    const result = await exponentialBackoff(fn, 3, 1);
    expect(result).toEqual({ success: true, value: "ok" });
    expect(fn).toHaveBeenCalledTimes(2);
  });

  it("returns failure after exhausting all retries", async () => {
    const fn = vi.fn().mockRejectedValue(new Error("always fails"));
    const result = await exponentialBackoff(fn, 2, 1);
    expect(result.success).toBe(false);
    if (!result.success) {
      expect(result.error).toContain("always fails");
    }
    expect(fn).toHaveBeenCalledTimes(2);
  });

  it("handles rate-limit errors (429)", async () => {
    const fn = vi
      .fn()
      .mockRejectedValueOnce(new Error("429 Too Many Requests"))
      .mockResolvedValue("done");
    const result = await exponentialBackoff(fn, 3, 1);
    expect(result).toEqual({ success: true, value: "done" });
  });

  it("handles RESOURCE_EXHAUSTED errors", async () => {
    const fn = vi
      .fn()
      .mockRejectedValueOnce(new Error("RESOURCE_EXHAUSTED"))
      .mockResolvedValue("done");
    const result = await exponentialBackoff(fn, 3, 1);
    expect(result).toEqual({ success: true, value: "done" });
  });

  it("handles quota errors", async () => {
    const fn = vi
      .fn()
      .mockRejectedValueOnce(new Error("Quota exceeded"))
      .mockResolvedValue("done");
    const result = await exponentialBackoff(fn, 3, 1);
    expect(result).toEqual({ success: true, value: "done" });
  });

  it("returns failure when maxRetries is 1 and fn throws", async () => {
    const fn = vi.fn().mockRejectedValue(new Error("fail"));
    const result = await exponentialBackoff(fn, 1, 1);
    expect(result.success).toBe(false);
    expect(fn).toHaveBeenCalledTimes(1);
  });
});

# Per-Project Action Brief Implementation Plan

> **For agentic workers:** REQUIRED SUB-SKILL: Use superpowers:subagent-driven-development (recommended) or superpowers:executing-plans to implement this plan task-by-task. Steps use checkbox (`- [ ]`) syntax for tracking.

**Goal:** Synthesize each project's mapped learnings into 3–5 prioritized actions, surfaced on the `/project/<name>` dashboard page and in per-repo `IDEAS.md` files.

**Architecture:** A new incremental agent (`project-brief.ts`) reads `project_mappings.json` + `knowledge_base.json`, LLM-synthesizes a per-project brief (hash-gated cache in `videos/project_briefs.json`), runs as a pipeline step after project mapping. The data builder emits `dashboard/data/briefs.json`; the project page renders an "Actions to try" section; the ideas-writer replaces per-learning blocks with a marked, replaceable brief section.

**Tech Stack:** TypeScript ESM (Node ≥24), `@juspay/neurolink` (Vertex `gemini-2.5-flash`, structured JSON), `node:sqlite` (unused here — briefs read JSON state), Svelte 5 (runes), vitest.

## Global Constraints

- Strict TS, no `any` (use `unknown` + narrowing). Named exports only. Functional/immutable.
- `neurolink.generate({ provider:"vertex", model, schema, output:{format:"json"}, disableTools:true })` for structured calls.
- All state writes atomic (tmp + rename). State reads tolerate missing/corrupt files.
- Model text passed to files/markdown must be neutralised (`mdSafe`) against `<!--`/`-->`.
- `juspay/dopamine` is PUBLIC: no personal paths/usernames in committed code. `projects.json` / `project_mappings.json` / `project_briefs.json` / `IDEAS.md` are personal/gitignored.
- Mirror any shared shape in BOTH `src/dashboard/data-builder.ts` and `web/src/lib/types.ts`.

